import{_ as e,o as a,c as r,ae as o}from"./chunks/framework.D3uQw3tB.js";const p=JSON.parse('{"title":"Desktop App","description":"","frontmatter":{},"headers":[],"relativePath":"usage-electron.md","filePath":"usage-electron.md"}'),s={name:"usage-electron.md"};function n(i,t,l,d,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="desktop-app" tabindex="-1">Desktop App <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop App&quot;">​</a></h1><p>The Electron app provides visual deck management with real-time sync to the MCP server.</p><h2 id="deck-list" tabindex="-1">Deck List <a class="header-anchor" href="#deck-list" aria-label="Permalink to &quot;Deck List&quot;">​</a></h2><p>The main screen shows all your decks with format badges, card counts, and progress bars. Use <strong>Cmd+N</strong> to create a new deck.</p><h2 id="deck-detail" tabindex="-1">Deck Detail <a class="header-anchor" href="#deck-detail" aria-label="Permalink to &quot;Deck Detail&quot;">​</a></h2><p>Click a deck to open the detail view. From here you can:</p><ul><li><strong>Add cards</strong> using the quick-add bar with Scryfall autocomplete</li><li><strong>Group cards</strong> by role, type, or custom categories</li><li><strong>Edit cards</strong> — change roles, ownership status, or move between mainboard, sideboard, and alternates</li><li><strong>View the mana curve</strong> with filtering by card type</li></ul><p>Press <strong>Esc</strong> to return to the deck list.</p><h2 id="card-management" tabindex="-1">Card Management <a class="header-anchor" href="#card-management" aria-label="Permalink to &quot;Card Management&quot;">​</a></h2><p>Each card tracks:</p><ul><li><strong>Ownership</strong>: unknown (default), owned, or need to buy</li><li><strong>Roles</strong>: functional tags like &quot;Ramp&quot;, &quot;Removal&quot;, &quot;Draw&quot;, etc.</li><li><strong>List</strong>: mainboard, sideboard, alternates, or cut</li></ul><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The Settings page lets you:</p><ul><li>Configure global roles</li><li>Connect/disconnect Claude Desktop integration</li><li>View storage location</li></ul><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Cmd+N</td><td>Create new deck</td></tr><tr><td>Esc</td><td>Go back to deck list</td></tr></tbody></table>',16)])])}const g=e(s,[["render",n]]);export{p as __pageData,g as default};
